ALTER TABLE public.profiles ADD COLUMN tiene_password boolean NOT NULL DEFAULT false;
UPDATE public.profiles p SET tiene_password=coalesce(u.encrypted_password,'')<>'' FROM auth.users u WHERE u.id=p.id;
ALTER TABLE public.visitas ADD COLUMN socio_eliminado boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.sesion_google() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT a->>'method'='oauth' FROM jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a WHERE a->>'method' IN ('oauth','password') ORDER BY (a->>'timestamp')::numeric DESC LIMIT 1),false) AND EXISTS(SELECT 1 FROM auth.identities WHERE user_id=auth.uid() AND provider='google') $$;
REVOKE ALL ON FUNCTION public.sesion_google() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sesion_google() TO authenticated;
CREATE OR REPLACE FUNCTION public.estado_acceso_personal() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; g:=public.sesion_google(); UPDATE public.profiles SET debe_cambiar_password=CASE WHEN g THEN false ELSE EXISTS(SELECT 1 FROM public.password_cambios WHERE user_id=auth.uid()) END WHERE id=auth.uid(); RETURN (SELECT jsonb_build_object('tiene_password',coalesce(p.tiene_password,false),'ha_accedido',u.last_sign_in_at IS NOT NULL,'debe_cambiar_password',coalesce(p.debe_cambiar_password,false),'google',g) FROM auth.users u LEFT JOIN public.profiles p ON p.id=u.id WHERE u.id=auth.uid()); END $$;
CREATE OR REPLACE FUNCTION public.acceso_usuario_admin(p_email text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=lower(trim(p_email))) THEN RAISE EXCEPTION 'Persona no disponible'; END IF; SELECT a.id,a.last_sign_in_at,coalesce(p.tiene_password,false) AS password INTO u FROM auth.users a LEFT JOIN public.profiles p ON p.id=a.id WHERE lower(a.email)=lower(trim(p_email)); RETURN jsonb_build_object('tiene_password',coalesce(u.password,false),'ultimo_acceso',u.last_sign_in_at,'puede_google',lower(trim(p_email)) ~ '@(gmail|googlemail)\.com$' OR EXISTS(SELECT 1 FROM auth.identities WHERE user_id=u.id AND provider='google')); END $$;
REVOKE ALL ON FUNCTION public.acceso_usuario_admin(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.acceso_usuario_admin(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.registrar_password_usuario(p_actor uuid,p_usuario uuid,p_email text,p_accion text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tiene boolean; BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=p_actor AND activo AND rol='super_admin') THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF p_accion NOT IN ('password_inicial','password_cambiada_admin','password_eliminada','usuario_sin_password') OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_usuario AND lower(email)=lower(trim(p_email)) AND email_confirmed_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=lower(trim(p_email)) AND activo) THEN RAISE EXCEPTION 'No autorizado'; END IF; IF p_accion='password_eliminada' AND NOT (lower(trim(p_email)) ~ '@(gmail|googlemail)\.com$' OR EXISTS(SELECT 1 FROM auth.identities WHERE user_id=p_usuario AND provider='google')) THEN RAISE EXCEPTION 'No tiene otra forma de entrar'; END IF; tiene:=p_accion IN ('password_inicial','password_cambiada_admin'); INSERT INTO public.profiles(id,email) VALUES(p_usuario,lower(trim(p_email))) ON CONFLICT(id) DO NOTHING; UPDATE public.profiles SET tiene_password=tiene,debe_cambiar_password=tiene WHERE id=p_usuario; IF tiene THEN INSERT INTO public.password_cambios(user_id,password_anterior) SELECT id,encrypted_password FROM auth.users WHERE id=p_usuario ON CONFLICT(user_id) DO UPDATE SET password_anterior=excluded.password_anterior; ELSE DELETE FROM public.password_cambios WHERE user_id=p_usuario; END IF; UPDATE public.usuario_roles SET user_id=p_usuario WHERE email=lower(trim(p_email)) AND activo; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(p_actor,p_usuario,p_accion,'Acceso gestionado por Super admin'); END $$;
CREATE OR REPLACE FUNCTION public.completar_cambio_password() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; IF EXISTS(SELECT 1 FROM public.password_cambios c JOIN auth.users u ON u.id=c.user_id WHERE c.user_id=auth.uid() AND (coalesce(u.encrypted_password,'')='' OR u.encrypted_password=c.password_anterior)) THEN RAISE EXCEPTION 'Guarda primero tu nueva contraseña'; END IF; UPDATE public.profiles SET debe_cambiar_password=false,tiene_password=true WHERE id=auth.uid(); DELETE FROM public.password_cambios WHERE user_id=auth.uid(); END $$;
CREATE OR REPLACE FUNCTION public.preparar_eliminar_socio(p_socio uuid,p_nombre text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; u uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; SELECT * INTO s FROM public.socios WHERE id=p_socio; IF NOT FOUND OR p_nombre IS DISTINCT FROM s.nombre THEN RAISE EXCEPTION 'Escribe el nombre completo'; END IF; SELECT id INTO u FROM auth.users WHERE lower(email)=lower(s.email); IF u=auth.uid() OR EXISTS(SELECT 1 FROM public.usuario_roles WHERE socio_id=p_socio AND user_id=auth.uid()) THEN RAISE EXCEPTION 'No puedes eliminarte a ti mismo'; END IF; RETURN jsonb_build_object('usuario',u); END $$;
REVOKE ALL ON FUNCTION public.preparar_eliminar_socio(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.preparar_eliminar_socio(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.eliminar_socio_admin(p_actor uuid,p_socio uuid,p_nombre text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; u uuid; otros boolean; BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=p_actor AND rol='super_admin' AND activo) THEN RAISE EXCEPTION 'Solo Super admin'; END IF; SELECT * INTO s FROM public.socios WHERE id=p_socio FOR UPDATE; IF NOT FOUND OR s.nombre IS DISTINCT FROM p_nombre THEN RAISE EXCEPTION 'Escribe el nombre completo'; END IF; SELECT id INTO u FROM auth.users WHERE lower(email)=lower(s.email); IF u=p_actor OR EXISTS(SELECT 1 FROM public.usuario_roles WHERE socio_id=p_socio AND user_id=p_actor) THEN RAISE EXCEPTION 'No puedes eliminarte a ti mismo'; END IF; PERFORM set_config('club.test_write','yes',true); UPDATE public.visitas SET socio_id=null,socio_eliminado=true WHERE socio_id=p_socio; DELETE FROM public.avisos_leidos WHERE socio_id=p_socio; DELETE FROM public.pagos WHERE socio_id=p_socio; DELETE FROM public.usuario_roles WHERE (socio_id=p_socio OR email=lower(s.email)) AND rol='socia'; UPDATE public.usuario_roles SET socio_id=null WHERE socio_id=p_socio; DELETE FROM public.user_roles WHERE user_id=u AND role='socia'; UPDATE public.profiles SET socio_id=null WHERE socio_id=p_socio; DELETE FROM public.solicitudes_socios WHERE socio_id=p_socio; DELETE FROM public.equipo_invitaciones WHERE socio_id=p_socio; SELECT EXISTS(SELECT 1 FROM public.usuario_roles WHERE (user_id=u OR email=lower(s.email)) AND rol IN ('directiva','negocio','super_admin')) INTO otros; IF NOT otros THEN DELETE FROM public.avisos_leidos WHERE user_id=u; DELETE FROM public.usuario_vista WHERE user_id=u; DELETE FROM public.usuario_roles WHERE user_id=u OR email=lower(s.email); END IF; DELETE FROM public.socios WHERE id=p_socio; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(p_actor,u,'eliminar_socio',s.nombre||' · nº '||s.numero_socio); RETURN jsonb_build_object('usuario',u,'borrar_auth',NOT otros AND u IS NOT NULL); END $$;
REVOKE ALL ON FUNCTION public.eliminar_socio_admin(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.eliminar_socio_admin(uuid,uuid,text) TO service_role;